import{c as e,Q as a,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"When \\\\\\"Better\\\\\\" Prompts Hurt: Evaluation-Driven Iteration for LLM Applications","description":"","frontmatter":{"url":"https://arxiv.org/abs/2601.22025","title":"When \\\\\\\\\\\\\\"Better\\\\\\\\\\\\\\" Prompts Hurt: Evaluation-Driven Iteration for LLM Applications","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2601.22025,"authors":["Daniel Commey"],"pdf_path":"pdfs/2601.22025.pdf","published_date":"2026-01-29T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-01-29-when-better-prompts-hurt-eval-driven-2601-22025.md","filePath":"research/papers/2026-01-29-when-better-prompts-hurt-eval-driven-2601-22025.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-01-29-when-better-prompts-hurt-eval-driven-2601-22025.md"};function o(s,t,l,d,p,m){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="when-better-prompts-hurt-evaluation-driven-iteration-for-llm-applications" tabindex="-1">When &quot;Better&quot; Prompts Hurt: Evaluation-Driven Iteration for LLM Applications <a class="header-anchor" href="#when-better-prompts-hurt-evaluation-driven-iteration-for-llm-applications" aria-label="Permalink to &quot;When &quot;Better&quot; Prompts Hurt: Evaluation-Driven Iteration for LLM Applications&quot;">​</a></h1><p><strong>Authors</strong>: Daniel Commey <strong>Published</strong>: January 29, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2601.22025" target="_blank" rel="noreferrer">https://arxiv.org/abs/2601.22025</a><strong>arXiv ID</strong>: 2601.22025 <strong>Categories</strong>: cs.CL</p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>Evaluating Large Language Model (LLM) applications differs from traditional software testing because outputs are stochastic, high-dimensional, and sensitive to prompt and model changes. We present an evaluation-driven workflow—Define, Test, Diagnose, Fix—that turns these challenges into a repeatable engineering loop.</p><p>We introduce the Minimum Viable Evaluation Suite (MVES), a tiered set of recommended evaluation components for (i) general LLM applications, (ii) retrieval-augmented generation (RAG), and (iii) agentic tool-use workflows. We also synthesize common evaluation methods (automated checks, human rubrics, and LLM-as-judge) and discuss known judge failure modes.</p><p>In reproducible local experiments (Ollama; Llama 3 8B Instruct and Qwen 2.5 7B Instruct), we observe that a generic &quot;improved&quot; prompt template can trade off behaviors: on our small structured suites, extraction pass rate decreased from 100% to 90% and RAG compliance from 93.3% to 80% for Llama 3 when replacing task-specific prompts with generic rules, while instruction-following improved. These findings motivate evaluation-driven prompt iteration and careful claim calibration rather than universal prompt recipes.</p><p>All test suites, harnesses, and results are included for reproducibility.</p><hr><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><h3 id="define-test-diagnose-fix-工作流程" tabindex="-1">Define-Test-Diagnose-Fix 工作流程 <a class="header-anchor" href="#define-test-diagnose-fix-工作流程" aria-label="Permalink to &quot;Define-Test-Diagnose-Fix 工作流程&quot;">​</a></h3><p>評估驅動的四階段迭代循環，取代傳統的「prompt 試錯」模式：</p><ol><li><strong>Define</strong>：將需求轉換為具體可測試的成功條件</li><li><strong>Test</strong>：對 prompt 版本跑評估套件（自動化 + 人工 + LLM-as-judge）</li><li><strong>Diagnose</strong>：分析失敗模式（prompt drift、format brittleness、silent regression）</li><li><strong>Fix</strong>：針對診斷結果做外科刀式修改，而非替換整個 prompt</li></ol><h3 id="mves-minimum-viable-evaluation-suite-三層架構" tabindex="-1">MVES（Minimum Viable Evaluation Suite）三層架構 <a class="header-anchor" href="#mves-minimum-viable-evaluation-suite-三層架構" aria-label="Permalink to &quot;MVES（Minimum Viable Evaluation Suite）三層架構&quot;">​</a></h3><table tabindex="0"><thead><tr><th>層級</th><th>應用類型</th><th>核心評估組件</th></tr></thead><tbody><tr><td>MVES-Core</td><td>一般 LLM 應用</td><td>自動化 checks + 人工 rubrics</td></tr><tr><td>MVES-RAG</td><td>RAG 系統</td><td>RAGAS 指標 + 引用覆蓋率</td></tr><tr><td>MVES-Agentic</td><td>Agent 工具使用</td><td>任務完成率 + 工具呼叫正確性</td></tr></tbody></table><h3 id="品質維度分類-quality-taxonomy" tabindex="-1">品質維度分類（Quality Taxonomy） <a class="header-anchor" href="#品質維度分類-quality-taxonomy" aria-label="Permalink to &quot;品質維度分類（Quality Taxonomy）&quot;">​</a></h3><p>七個維度：Correctness、Helpfulness、Harmlessness、Groundedness &amp; Attribution、Refusal Correctness、Format &amp; Style Adherence、Consistency。</p><h3 id="llm-as-judge-已知失敗模式" tabindex="-1">LLM-as-Judge 已知失敗模式 <a class="header-anchor" href="#llm-as-judge-已知失敗模式" aria-label="Permalink to &quot;LLM-as-Judge 已知失敗模式&quot;">​</a></h3><ul><li><strong>Position bias</strong>：傾向評分排在前面的答案</li><li><strong>Verbosity bias</strong>：偏好較長回應，即使內容較差</li><li><strong>Self-preference</strong>：同家族模型互相偏好</li><li><strong>Style bias</strong>：偏好特定格式（如 markdown）</li><li><strong>Instruction leakage</strong>：judge prompt 中的評分標準滲漏影響判斷</li></ul><hr><h2 id="關鍵數字" tabindex="-1">關鍵數字 <a class="header-anchor" href="#關鍵數字" aria-label="Permalink to &quot;關鍵數字&quot;">​</a></h2><table tabindex="0"><thead><tr><th>實驗對比</th><th>Task-specific prompt</th><th>Generic &quot;improved&quot; prompt</th><th>變化</th></tr></thead><tbody><tr><td>抽取 pass rate</td><td>100%</td><td>90%</td><td><strong>-10pp</strong></td></tr><tr><td>RAG compliance (Llama 3)</td><td>93.3%</td><td>80%</td><td><strong>-13.3pp</strong></td></tr><tr><td>Instruction-following</td><td>—</td><td>—</td><td>改善（唯一正向）</td></tr></tbody></table><p><strong>模型</strong>：Ollama + Llama 3 8B Instruct + Qwen 2.5 7B Instruct（本地推論，完全可重現）</p><hr><h2 id="對-prompt-caching-management-engineering-的關聯" tabindex="-1">對 Prompt Caching / Management / Engineering 的關聯 <a class="header-anchor" href="#對-prompt-caching-management-engineering-的關聯" aria-label="Permalink to &quot;對 Prompt Caching / Management / Engineering 的關聯&quot;">​</a></h2><h3 id="prompt-caching" tabindex="-1">Prompt Caching <a class="header-anchor" href="#prompt-caching" aria-label="Permalink to &quot;Prompt Caching&quot;">​</a></h3><ul><li><strong>Prompt Drift 偵測</strong>：本文的 MVES 可作為 caching 策略的回歸測試套件——若快取的 system prompt 被更動，必須跑 MVES 確認無 silent regression</li><li><strong>Silent Regression 風險</strong>：LLM provider 靜默更新模型時（model churn），快取的 KV 狀態對應的 prompt 行為可能改變；MVES 提供偵測這種漂移的機械性驗證方法</li></ul><h3 id="prompt-management" tabindex="-1">Prompt Management <a class="header-anchor" href="#prompt-management" aria-label="Permalink to &quot;Prompt Management&quot;">​</a></h3><ul><li><strong>Prompt 版本控管</strong>：Define-Test-Diagnose-Fix 循環直接對應 prompt 版本管理的工程紀律——每次修改都需要可測量的成功條件（R4 Goal-Driven）</li><li><strong>LLM-as-judge 評估成本</strong>：論文量化了不同評估方法的 cost per 1,000 examples，幫助決定 prompt 迭代的評估預算分配</li><li><strong>Overfitting to Test Set</strong>（§10.2）：對評估集過度優化的 prompt 在生產環境退化，與 prompt caching 情境中「對特定 case 最佳化的快取 prefix」面臨相同風險</li></ul><h3 id="prompt-engineering" tabindex="-1">Prompt Engineering <a class="header-anchor" href="#prompt-engineering" aria-label="Permalink to &quot;Prompt Engineering&quot;">​</a></h3><ul><li><strong>核心論點</strong>：反直覺發現——「更好」的通用 prompt 模板在特定任務上反而退步，支持任務特定評估優先於通用 prompt 秘訣</li><li><strong>MVES 框架</strong>：提供 prompt engineer 實際可執行的評估標準（非口頭「看起來正確」），直接對應 §R4 的「成功條件必須可機械性驗證」</li><li><strong>六大 Contribution</strong>：MVES 框架 + 評估方法綜述 + 品質維度分類 + LLM-as-judge 失敗模式分析 + actionable checklist + 原始實驗（全部開源可重現）</li></ul>',31)])])}const g=e(i,[["render",o]]);export{u as __pageData,g as default};
